async function shareSite(){const url=new URL('/',location.href).href;const info={title:'플랜티넷 그룹 · 인원현황 보고',text:'플랜티넷·플랜티엠 인원현황 보고 페이지',url};if(typeof navigator.share==='function'){try{await navigator.share(info);return;}catch(e){if(e.name==='AbortError')return;}}exportShell('웹페이지 링크 공유');$('#exportContent').innerHTML=`<p>아래 링크를 복사해 카카오톡·문자·메일 등으로 전달하세요.</p><input id="shareUrl" class="share-url" readonly value="${esc(url)}" aria-label="공유할 웹페이지 주소"><div class="actions"><button id="copySiteUrl" class="button primary">링크 복사</button></div><p id="shareStatus" class="mini" role="status" aria-live="polite">사이트 주소를 공유합니다. 업로드한 인사자료는 링크에 포함되지 않습니다.</p>`;$('#shareUrl').onclick=e=>e.target.select();$('#copySiteUrl').onclick=async()=>{try{await navigator.clipboard.writeText(url);$('#shareStatus').textContent='링크를 복사했습니다.';}catch(e){$('#shareUrl').focus();$('#shareUrl').select();$('#shareStatus').textContent='주소를 선택했습니다. 길게 눌러 복사하세요.';}};}
